"""Composable template framework used by mill_ui.

Design notes (optimized for Codex-generated templates):

- Treat every template like a UI tree: collect params into small dataclasses,
  build semantic regions, then emit primitive shapes via helpers.
- Prefer pure functions that return dictionaries; avoid mutating shared state.
- Keep helpers here so generated templates naturally follow the same pattern.
"""

from __future__ import annotations

from dataclasses import dataclass
from typing import Dict, Any, List, Tuple
import copy

REGISTRY: Dict[str, type] = {}

def register_template(name: str):
    def deco(cls):
        # Register with exact key and a lowercase alias so canonicalized
        # template types (e.g., from ingest) still resolve.
        REGISTRY[name] = cls
        REGISTRY.setdefault(name.lower(), cls)
        return cls
    return deco

class TemplateBase:
    def expand(self, params: Dict[str, Any], thickness_mm: float) -> List[Dict[str, Any]]:
        raise NotImplementedError


# ---------------------------------------------------------------------------
# Primitive helpers
# ---------------------------------------------------------------------------

def rect_shape(center_xy_mm: Tuple[float, float], *, width_mm: float, height_mm: float,
               feature: Dict[str, Any], shape_id: str) -> Dict[str, Any]:
    cx, cy = float(center_xy_mm[0]), float(center_xy_mm[1])
    return {
        "kind": "shape",
        "type": "Rect",
        "id": shape_id,
        "geometry": {"w_mm": float(width_mm), "h_mm": float(height_mm)},
        "placement": {"center_xy_mm": (cx, cy)},
        "feature": feature,
    }


def circle_shape(center_xy_mm: Tuple[float, float], *, diameter_mm: float,
                 feature: Dict[str, Any], shape_id: str) -> Dict[str, Any]:
    cx, cy = float(center_xy_mm[0]), float(center_xy_mm[1])
    return {
        "kind": "shape",
        "type": "Circle",
        "id": shape_id,
        "geometry": {"diameter_mm": float(diameter_mm)},
        "placement": {"center_xy_mm": (cx, cy)},
        "feature": feature,
    }


@dataclass(frozen=True)
class CenterRegion:
    """Simple centered rectangle region used by multiple templates."""

    width_mm: float
    height_mm: float

    @property
    def half_width(self) -> float:
        return float(self.width_mm) * 0.5

    @property
    def half_height(self) -> float:
        return float(self.height_mm) * 0.5

    def anchor_points(self, offsets: Dict[str, float]) -> List[Tuple[float, float]]:
        left = float(offsets.get("left", 0.0))
        right = float(offsets.get("right", 0.0))
        top = float(offsets.get("top", 0.0))
        bottom = float(offsets.get("bottom", 0.0))
        hx, hy = self.half_width, self.half_height
        return [
            (-hx + left,  +hy - top),
            (+hx - right, +hy - top),
            (-hx + left,  -hy + bottom),
            (+hx - right, -hy + bottom),
        ]

def _offset_items(items: List[Dict[str, Any]], center_xy_mm: Tuple[float, float]) -> List[Dict[str, Any]]:
    cx, cy = float(center_xy_mm[0]), float(center_xy_mm[1])
    out: List[Dict[str, Any]] = []
    for it in items:
        j = copy.deepcopy(it)
        plc = j.get("placement") or {}
        inner = plc.get("center_xy_mm")
        if isinstance(inner, (list, tuple)) and len(inner) == 2:
            j.setdefault("placement", {})["center_xy_mm"] = (float(inner[0]) + cx, float(inner[1]) + cy)
        else:
            j["placement"] = {"center_xy_mm": (cx, cy)}
        out.append(j)
    return out

def resolve_templates(items: List[Dict[str, Any]], *, sheet_thickness_mm: float) -> List[Dict[str, Any]]:
    """
    Expand template items into concrete shapes and ensure child IDs are UNIQUE per template.

    Why: seam-merging in the planner uses 'rect_id' to avoid pairing edges from the SAME rectangle.
    If different rectangles reuse the same child id (e.g., 'door:outer'), they will be treated
    as one part and internal seams won't merge. Prefixing with base template id fixes this.
    """
    out: List[Dict[str, Any]] = []
    for it in items:
        if it.get("kind") != "template":
            out.append(it)
            continue

        tname = it.get("type")
        params = it.get("params") or {}

        # placement center (applied to all children)
        center = None
        plc = it.get("placement") or {}
        v = plc.get("center_xy_mm")
        if isinstance(v, (list, tuple)) and len(v) == 2:
            center = (float(v[0]), float(v[1]))

        cls = REGISTRY.get(str(tname))
        if not cls:
            continue

        inst: TemplateBase = cls()
        built = inst.expand(params, sheet_thickness_mm)
        if center is not None:
            built = _offset_items(built, center)

        # --- ID threading: ALWAYS prefix child ids with the template's id ---
        base_id = (it.get("id") or "").strip()
        if base_id:
            for k, b in enumerate(built, start=1):
                child = (b.get("id") or "").strip()
                b["id"] = f"{base_id}:{child}" if child else f"{base_id}:{k}"
        else:
            # Ensure stable unique ids even if the template has no id
            for k, b in enumerate(built, start=1):
                if not b.get("id"):
                    b["id"] = f"item:{k}"

        out.extend(built)
    return out

"""Thin Python shims for the native CAM core.

The helpers defined here map the existing Python data structures into the POD
facade exposed by ``skills.mill_ui.cam.native._native``.  Public modules never
import the extension directly; they go through these wrappers so the native
engine remains the single source of truth for toolpath generation.
"""
from __future__ import annotations

from typing import Iterable, List, Optional, Sequence, Tuple

try:  # pragma: no cover - optional native module
    from . import _native  # type: ignore[attr-defined]
except Exception:  # pragma: no cover - surface a clear error when accessed
    _native = None  # type: ignore[assignment]


def is_native_available() -> bool:
    """Return True when the compiled pybind11 extension imported successfully."""
    return _native is not None


def _require_native() -> None:
    if _native is None:  # pragma: no cover - defensive guard
        raise RuntimeError(
            "skills.mill_ui.cam.native._native is not available. Install the project "
            "with a modern C++ toolchain so the native CAM core can be built."
        )


# ---------------------------------------------------------------------------
# Shared conversions
# ---------------------------------------------------------------------------

def _poly_from_shape(shape) -> List[Tuple[float, float]]:
    return [(float(pt.x), float(pt.y)) for pt in getattr(shape, "points", [])]


def _planar_face_dict(shape, depth_mm: float, safe_z_mm: float) -> dict:
    return {
        "z": 0.0,
        "depth": float(depth_mm),
        "safe_z": float(safe_z_mm),
        "outer": _poly_from_shape(shape),
        "holes": [],
    }


def _holes_from_points(points: Iterable[Tuple[float, float]], depth_mm: float, tool_diameter: float) -> List[dict]:
    holes = []
    for x, y in points:
        holes.append({
            "x": float(x),
            "y": float(y),
            "diameter": float(tool_diameter),
            "depth": float(depth_mm),
        })
    return holes


# ---------------------------------------------------------------------------
# Native-backed planners
# ---------------------------------------------------------------------------

def pocket_raster(shape, setup, *, depth_mm: float, stepover_mm: float, stepdown_mm: Optional[float]) -> List[dict]:
    _require_native()
    face = _planar_face_dict(shape, depth_mm, setup.safe_z)
    step_down_arg = None if stepdown_mm is None else float(stepdown_mm)
    return _native.plan_pocket(face, setup.tool, float(stepover_mm), step_down_arg)


def profile_outline(shape, setup, *, depth_mm: float, stepdown_mm: float) -> List[dict]:
    _require_native()
    boundary = _poly_from_shape(shape)
    return _native.plan_profile(boundary, setup.tool, float(depth_mm), float(stepdown_mm), float(setup.safe_z))


def drill_peck(points: Sequence[Tuple[float, float]], setup, *, depth_mm: float, peck_mm: float) -> List[dict]:
    _require_native()
    holes = _holes_from_points(points, depth_mm, setup.tool.diameter)
    return _native.plan_drill(holes, setup.tool, float(peck_mm), float(setup.safe_z))


def bore_helical(center_xy: Tuple[float, float], hole_d_mm: float, setup, *, depth_mm: float,
                 stepdown_mm: float) -> List[dict]:
    _require_native()
    hole = {
        "x": float(center_xy[0]),
        "y": float(center_xy[1]),
        "diameter": float(hole_d_mm),
        "depth": float(depth_mm),
    }
    return _native.plan_bore_helical(hole, setup.tool, float(stepdown_mm), float(setup.safe_z))


def post_gcode(moves: Sequence[dict], *, unit: str = "mm", prec: int = 3, safe_z: float = 5.0,
               header: Optional[Sequence[str]] = None, footer: Optional[Sequence[str]] = None) -> str:
    """Emit G-code via the native backend."""
    _require_native()
    cfg = {
        "unit": unit,
        "prec": int(prec),
        "safe_z": float(safe_z),
    }
    if header is not None:
        cfg["header"] = list(header)
    if footer is not None:
        cfg["footer"] = list(footer)
    return _native.post_gcode(list(moves), cfg)


# ---------------------------------------------------------------------------
# Passthrough helpers exposed for completeness (not yet wired internally)
# ---------------------------------------------------------------------------

def load_step(path: str):
    _require_native()
    return _native.load_step(str(path))


def make_setup(model, tol_mm: float = 0.01):
    _require_native()
    return _native.make_setup(model, float(tol_mm))


def detect_planar(model, setup, tol_mm: float = 0.01):
    _require_native()
    return _native.detect_planar(model, setup, float(tol_mm))


def detect_holes(model, setup, tol_mm: float = 0.01):
    _require_native()
    return _native.detect_holes(model, setup, float(tol_mm))


def offset_inset(polygon: Iterable[Iterable[float]], radius_mm: float):
    _require_native()
    pts = [[float(x), float(y)] for x, y in polygon]
    return _native.offset_inset(pts, float(radius_mm))


def offset_outset(polygon: Iterable[Iterable[float]], radius_mm: float):
    _require_native()
    pts = [[float(x), float(y)] for x, y in polygon]
    return _native.offset_outset(pts, float(radius_mm))


def create_stock(minx: float, miny: float, maxx: float, maxy: float, pitch_mm: float):
    _require_native()
    return _native.create_stock(float(minx), float(miny), float(maxx), float(maxy), float(pitch_mm))


def link_keepdown(paths, safe_z: float, min_clearance: float):
    _require_native()
    return _native.link_keepdown(paths, float(safe_z), float(min_clearance))


def fit_arcs(paths, tol_mm: float):
    _require_native()
    return _native.fit_arcs(paths, float(tol_mm))


# ---------------------------------------------------------------------------
# Mandelbrot helpers (native)
# ---------------------------------------------------------------------------

def mandelbrot_outline_fill(
    *,
    width_mm: float,
    height_mm: float,
    resolution_x: int,
    resolution_y: int,
    iterations: int = 100,
    escape_radius: float = 2.0,
    real_min: float = -2.0,
    real_max: float = 1.0,
    imag_min: float = -1.25,
    imag_max: float = 1.25,
):
    """Return dict with 'polylines' and 'spans' for a Mandelbrot outline + fill.

    polylines: list[list[tuple[float,float]]] in panel mm coords (origin center)
    spans:     list[dict{x0,x1,y,h}] horizontal runs for pocket rectangles
    """
    _require_native()
    return _native.mandelbrot_outline_fill(
        float(width_mm),
        float(height_mm),
        int(resolution_x),
        int(resolution_y),
        int(iterations),
        float(escape_radius),
        float(real_min),
        float(real_max),
        float(imag_min),
        float(imag_max),
    )

"""Profile planning helpers."""
from __future__ import annotations

from typing import Any, Dict, Mapping, Tuple

from skills.mill_ui.core.types import Vec2
from skills.mill_ui.cad.primitives import rectangle, circle as circle_shape
from skills.mill_ui.cad.transforms import Transform2D, place
from skills.mill_ui.cad.shape import Shape2D
from skills.mill_ui.cam.model.setup import Setup
from skills.mill_ui.cam.ops.profile import profile_outline
from skills.mill_ui.cam.path.strategies import (
    onion_skin_then_finish,
    profile_outline_with_tabs,
)
from skills.mill_ui.cam.planner.registry import register_strategy

from .tools import ToolSelection, stepdown_for_tool


def rect_shape(width: float, height: float, center: Tuple[float, float]) -> Shape2D:
    base = rectangle(width, height)
    cx, cy = center
    return place(base, Transform2D(tx=cx - width / 2.0, ty=cy - height / 2.0))


def circle_shape_mm(diameter: float, center: Tuple[float, float]) -> Shape2D:
    cx, cy = center
    return circle_shape(Vec2(cx, cy), diameter / 2.0)


def ensure_center(record: Mapping[str, Any]) -> Tuple[float, float]:
    placement = record.get("placement") if isinstance(record.get("placement"), Mapping) else None
    if placement is not None:
        value = placement.get("center_xy_mm")
        if isinstance(value, (list, tuple)) and len(value) == 2:
            return float(value[0]), float(value[1])

    direct = record.get("center_xy_mm")
    if isinstance(direct, (list, tuple)) and len(direct) == 2:
        return float(direct[0]), float(direct[1])
    return 0.0, 0.0


def offset_rect_shape(width: float, height: float, center: Tuple[float, float], offset: float) -> Shape2D | None:
    width_expanded = width + 2.0 * offset
    height_expanded = height + 2.0 * offset
    if width_expanded <= 0.0 or height_expanded <= 0.0:
        return None
    return rect_shape(width_expanded, height_expanded, center)


def offset_circle_shape(diameter: float, center: Tuple[float, float], offset: float) -> Shape2D | None:
    expanded = diameter + 2.0 * offset
    if expanded <= 0.0:
        return None
    return circle_shape_mm(expanded, center)


def profile_moves_with_options(
    shape: Shape2D,
    *,
    setup: Setup,
    depth_mm: float,
    tool: ToolSelection,
    onion_skin_mm: float,
    tabs_opts: Mapping[str, Any] | None,
) -> list[Dict[str, Any]]:
    step_down = stepdown_for_tool(tool)

    tabs = tabs_opts if isinstance(tabs_opts, Mapping) else {}
    tabs_count = int(tabs.get("count", 0) or 0)
    onion_skin_positive = onion_skin_mm > 0.0
    tabs_enabled = tabs_count > 0

    if onion_skin_positive and tabs_enabled:
        raise ValueError("Onion skin and tabs cannot be combined in the same profile pass")

    if onion_skin_positive:
        return onion_skin_then_finish(
            shape,
            setup,
            total_depth_mm=depth_mm,
            skin_mm=onion_skin_mm,
            step_down_mm=step_down,
        )

    if tabs_enabled:
        tab_height = float(tabs.get("height_mm", 3.0))
        tab_width = tabs.get("width_mm")
        tab_width_val = float(tab_width) if tab_width is not None else None
        return profile_outline_with_tabs(
            shape,
            setup,
            depth_mm=depth_mm,
            step_down_mm=step_down,
            tab_count=max(1, tabs_count),
            tab_height_mm=max(0.1, tab_height),
            tab_width_mm=tab_width_val,
        )

    return profile_outline(shape, setup, depth_mm, step_down=step_down)


def _profile_plain(
    shape: Shape2D,
    setup: Setup,
    *,
    depth_mm: float,
    tool: ToolSelection,
    **_: Any,
) -> list[Dict[str, Any]]:
    return profile_outline(shape, setup, depth_mm, step_down=stepdown_for_tool(tool))


register_strategy("profile", "onion_skin", onion_skin_then_finish)
register_strategy("profile", "tabs", profile_outline_with_tabs)
register_strategy("profile", "plain", _profile_plain)


__all__ = [
    "circle_shape_mm",
    "ensure_center",
    "offset_circle_shape",
    "offset_rect_shape",
    "profile_moves_with_options",
    "rect_shape",
]

